WITH subscriptions_by_customer AS (SELECT customer_id, ROUND((100 * SUM(CASE WHEN plan = 'basic' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_basic, MAX(end_date) AS latest_end_date FROM subscriptions WHERE monthly_fee BETWEEN 140 AND 180 GROUP BY customer_id) SELECT c.age, sbc.pct_basic, sbc.latest_end_date FROM customers c JOIN subscriptions_by_customer sbc ON c.id = sbc.customer_id;
